// 01. Votes and supports
// ----------------------

@mixin supports {
  padding: $line-height 0;
  position: relative;

  .progress {
    background: color.adjust($proposals, $lightness: 35%);
    border: 1px solid color.adjust($proposals, $lightness: 35%);
    height: rem-calc(14);
    position: relative;

    .meter {
      background: $proposals;
      border-radius: 0;
      border-bottom-right-radius: rem-calc(3);
      border-top-right-radius: rem-calc(3);
      display: block;
      height: calc($line-height / 2);
    }
  }

  .percentage {
    font-size: $tiny-font-size;
    position: absolute;
    right: 6px;
    top: -2px;
    vertical-align: top;
  }

  abbr {
    color: $text-medium;

    &[title] {
      border-bottom: 0;
    }
  }

  .button-support {
    background: $proposals;
    color: inherit;
    display: inline-block;
    font-size: $small-font-size;
    margin-top: rem-calc(12);

    &:hover,
    &:active {
      background: color.adjust($proposals, $lightness: 25%);
      cursor: pointer;
    }
  }

  .total-supports {
    display: block;
    font-weight: bold;
    text-align: center;

    span {
      display: block;
      font-size: $small-font-size;
      font-weight: normal;
    }
  }

  .supported {
    color: inherit;
    margin-top: rem-calc(12);
  }
}

.participation-not-allowed {
  background: $warning-bg;
  color: $color-warning;
  display: none;
  line-height: $line-height;
  padding: calc($line-height / 2);
  text-align: center;
  width: 100%;

  &,
  p {
    font-size: $small-font-size;
  }

  p {
    color: inherit !important;
    margin: 0 rem-calc(12);
    text-align: left;
  }

  a {
    color: inherit !important;
    font-weight: bold;
    text-decoration: underline;
  }
}

