import sys, pathlib, re
# usage: file "header substring" [...]
path=pathlib.Path(sys.argv[1]); headers=sys.argv[2:]
lines=path.read_text().splitlines(True)
for header in headers:
    i=0
    while i < len(lines):
        if header in lines[i] and re.search(r'\b(describe|context)\b', lines[i]):
            indent=len(lines[i])-len(lines[i].lstrip())
            # find matching end at same indent: line stripped == 'end'
            j=i+1; depth=1
            # Simple ruby block counting by lines starting with describe/context/it/def/begin/if etc is hard.
            # Instead find next line with indent== and stripped end, assuming block's immediate end is first such after nested blocks increased indent - nested ends have higher indent in formatted code.
            while j < len(lines):
                if len(lines[j])-len(lines[j].lstrip())==indent and lines[j].strip()=="end":
                    break
                j+=1
            # delete i..j plus following blank
            del lines[i:j+1]
            if i < len(lines) and lines[i].strip()=="": del lines[i]
            break
        i+=1
    else:
        print(f"block not found {header} in {path}")
path.write_text(''.join(lines))
